{
  "positionId": "P01",
  "interviews": [
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I1",
      "interviewBlueprint": {
        "questionIntent": "느린 조회 쿼리의 병목에 맞는 개선 방법을 선택할 수 있는지 검증한다. 실행 계획에서 확인한 문제를 인덱스 추가 결정으로 연결한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓 운영 화면의 신고 목록 조회 쿼리가 3.2초 걸리던 상황이다.",
          "task": "조회 병목에 적합한 개선 방법으로 인덱스 추가가 필요한지 판단해야 했다.",
          "action": "실행 계획과 조회 조건에서 확인한 사실을 근거로 인덱스 추가를 선택한 이유를 설명한다.",
          "result": "확인한 병목과 인덱스 추가 결정 사이의 연결이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "조회 속도를 높이는 방법으로 인덱스 추가를 선택한 근거",
          "그 근거가 된 실행 계획의 조회 방식이나 조회 조건에 관한 구체적인 사실",
          "해당 사실을 바탕으로 인덱스가 불필요한 조회 작업을 줄인다고 판단한 연결"
        ]
      },
      "question": "포켓마켓에서 신고 목록 조회를 3.2초에서 0.4초로 줄이셨던데요, 그때 조회 속도를 높이는 방법으로 인덱스 추가를 선택한 근거는 무엇이었어요?",
      "answerTip": "당시 경험을 떠올리며 차분히 답해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "인덱스 추가를 선택한 근거를 실제 실행 계획이나 조회 조건에서 확인한 사실로 구체적으로 설명한다.",
            "확인한 조회 병목을 인덱스가 줄일 수 있는 이유가 기술적으로 타당하게 연결된다."
          ]
        },
        "acceptable": {
          "criteria": [
            "인덱스 추가를 선택한 근거와 관련된 조회 문제를 제시하지만, 실행 계획이나 조회 조건에 관한 설명이 제한적이다.",
            "인덱스와 조회 작업 감소의 관계는 설명하나 해당 쿼리의 병목과 연결하는 구체성이 부족하다."
          ]
        },
        "poor": {
          "criteria": [
            "인덱스를 추가했다는 사실만 반복하고 선택 근거를 제시하지 못한다.",
            "확인한 조회 문제와 인덱스의 작동 방식 사이의 연결이 없거나 기술적으로 타당하지 않다."
          ]
        }
      }
    },
    {
      "categoryId": "P01-C2",
      "itemId": "P01-C2-I2",
      "interviewBlueprint": {
        "questionIntent": "로그로 파악한 운영 오류의 원인에 맞게 수정 조치를 판단할 수 있는지 검증한다. 두 서버의 스케줄러 중복 실행을 막는 수정에서 중요하게 판단한 지점에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "포켓마켓에서 배포 후 알림이 중복 발송되어 로그로 스케줄러의 동시 실행을 확인한 상황이다.",
          "task": "서버 두 대에서 발생하는 스케줄러 중복 실행을 막도록 수정해야 했다.",
          "action": "수정에서 가장 중요하게 판단한 지점과 그 판단이 잠금 키를 사용하는 방식에 반영된 내용을 설명한다.",
          "result": "확인한 장애 원인을 차단하려는 수정 판단이 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "스케줄러 중복 실행을 막는 수정에서 가장 중요하게 판단한 지점",
          "그 판단의 근거가 된 두 서버의 동시 실행 상황",
          "중요하게 판단한 지점을 잠금 키의 동작에 반영해 중복 실행을 차단한 설명"
        ]
      },
      "question": "포켓마켓에서 배포 후 알림 중복 발송을 잠금 키로 고치셨던데요, 그때 스케줄러 중복 실행을 막는 수정에서 가장 신경 쓴 점은 무엇이었어요?",
      "answerTip": "본인이 했던 일을 중심으로 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "수정에서 가장 중요하게 판단한 지점을 두 서버의 동시 실행 상황에 근거해 구체적으로 설명한다.",
            "해당 판단이 잠금 키의 동작에 반영되어 중복 실행을 차단하는 연결을 기술적으로 타당하게 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "수정에서 중요하게 판단한 지점을 제시하고 두 서버의 동시 실행과 관련짓지만 설명이 부분적이다.",
            "잠금 키로 중복 실행을 막았다고 설명하나 중요하게 판단한 지점이 실제 동작에 반영된 내용은 불분명하다."
          ]
        },
        "poor": {
          "criteria": [
            "잠금 키를 사용했다는 사실만 말하고 수정에서 중요하게 판단한 지점을 제시하지 못한다.",
            "설명한 수정 방식이 두 서버의 동시 실행을 차단하는 이유가 없거나 기술적으로 타당하지 않다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P02",
  "interviews": [
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "현업·사용자 요청을 구현 범위로 구체화하는 판단을 검증한다. 요구사항에 포함할 범위를 정한 기준에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 인터뷰로 수집한 요청을 바탕으로 개발 담당 팀원과 구현 범위를 조정한 상황이다.",
          "task": "요청의 목적에 맞춰 요구사항에 포함할 범위를 정해야 한다.",
          "action": "요청에서 확인한 필요를 근거로 범위 판단 기준을 세우고 실제 포함 여부를 결정한 내용을 설명한다.",
          "result": "범위 판단 기준과 그 기준으로 정한 요구사항 범위가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "요구사항에 포함할 범위를 정할 때 적용한 판단 기준",
          "그 기준의 근거가 된 요청의 목적이나 사용자 필요",
          "판단 기준이 실제 요구사항의 포함 여부로 이어진 연결"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 개발 담당 팀원과 범위를 조정하셨던데요, 그때 요구사항에 포함할 범위를 정한 기준은 무엇이었어요?",
      "answerTip": "기억나는 장면 하나를 중심으로 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "범위 판단 기준을 구체적으로 제시하고 요청의 목적이나 사용자 필요에 비추어 타당하게 설명한다.",
            "실제 요구사항의 포함 여부를 제시하며 해당 기준이 결정에 적용된 연결을 명확히 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "범위 판단 기준은 제시하지만 요청의 목적이나 사용자 필요와 연결한 설명이 부족하다.",
            "요구사항의 포함 여부는 드러나지만 판단 기준이 해당 결정에 적용된 설명이 부분적이다."
          ]
        },
        "poor": {
          "criteria": [
            "범위를 정한 기준을 제시하지 못하거나 요청의 목적과 무관한 기준만 이야기한다.",
            "요청을 정리했다는 설명에 그쳐 실제 포함 여부와 판단 기준의 연결이 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P02-C1",
      "itemId": "P02-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "예외 상황을 개발·디자인 담당자가 구현할 수 있는 화면 동작으로 구체화하는 판단을 검증한다. 예외 화면의 동작을 정하면서 가장 신경 쓴 점에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "동네 세탁소 예약 서비스 기획에서 예외 상황을 포함한 화면설계서를 작성한 상황이다.",
          "task": "예외 상황에서 화면이 보일 동작을 구현 가능한 수준으로 정해야 한다.",
          "action": "예외 화면의 동작을 정할 때 가장 신경 쓴 점을 실제 설계 내용에 근거해 설명한다.",
          "result": "중점을 둔 사항이 구체적인 예외 화면 동작으로 드러난다."
        },
        "expectedEvidence": [
          "예외 화면의 동작을 정할 때 가장 신경 쓴 점",
          "해당 판단이 필요했던 구체적인 예외 상황",
          "신경 쓴 점이 실제로 설계한 화면 동작에 반영된 내용"
        ]
      },
      "question": "동네 세탁소 예약 서비스 기획에서 예외 상황을 담은 화면설계서 28장을 작성하셨던데요, 그때 예외 화면의 동작을 정하며 가장 신경 쓴 점은 뭐였어요?",
      "answerTip": "직접 했던 일을 떠올리며 차분히 말해 보세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "예외 화면의 동작을 정할 때 중점을 둔 사항을 구체적인 예외 상황에 맞춰 타당하게 설명한다.",
            "그 사항이 반영된 화면 동작을 구현 내용을 이해할 수 있을 만큼 구체적으로 제시한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "중점을 둔 사항과 예외 상황은 제시하지만 둘 사이의 연결이 충분히 설명되지 않는다.",
            "관련 화면 동작을 제시하지만 중점을 둔 사항이 설계에 반영된 내용은 부분적으로만 드러난다."
          ]
        },
        "poor": {
          "criteria": [
            "중점을 둔 사항을 제시하지 못하거나 구체적인 예외 상황과 무관한 일반 원칙만 이야기한다.",
            "화면설계서를 작성했다는 설명에 그쳐 실제 예외 화면 동작과의 연결이 드러나지 않는다."
          ]
        }
      }
    }
  ]
}

{
  "positionId": "P03",
  "interviews": [
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I1",
      "interviewBlueprint": {
        "questionIntent": "의심스러운 처방을 확인 없이 수행하지 않는 판단을 검증한다. 평소와 다른 진통제 처방을 보고 투약을 중단하기로 한 근거에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "수술 후 환자에게 투여할 진통제 처방 용량이 평소와 달랐던 상황이다.",
          "task": "해당 처방대로 투약해도 되는지 판단해야 했다.",
          "action": "처방에서 확인한 이상과 확인되지 않은 내용을 근거로 투약을 멈추기로 판단한 이유를 설명한다.",
          "result": "처방 확인 전 투약을 진행하지 않기로 한 판단의 근거가 구체적으로 드러난다."
        },
        "expectedEvidence": [
          "해당 진통제의 투약을 멈추기로 판단한 근거",
          "평소 용량과 당시 처방 용량의 차이 등 의심을 갖게 된 구체적인 사실",
          "용량 차이의 타당성이 확인되지 않은 상태에서 투약을 진행할 수 없다고 본 이유"
        ]
      },
      "question": "푸른결종합병원에서 진통제 처방 용량이 평소의 두 배였던 적이 있다고 하셨는데요, 그때 투약을 멈추기로 판단한 근거는 무엇이었어요?",
      "answerTip": "당시 장면을 떠올리며 차분히 말씀해 주세요.",
      "evaluationRubric": {
        "excellent": {
          "criteria": [
            "투약을 멈춘 근거를 당시 처방에서 확인한 구체적인 사실로 설명한다.",
            "평소 용량과 당시 처방 용량의 차이를 명확히 짚는다.",
            "평소와 다르다는 사실만으로 오류를 단정하지 않고, 처방의 타당성이 확인되기 전에는 투약을 진행할 수 없다고 판단한 이유를 설명한다."
          ]
        },
        "acceptable": {
          "criteria": [
            "처방 용량이 평소와 달라 투약을 멈췄다는 핵심 근거는 제시한다.",
            "용량 차이나 확인되지 않은 처방을 그대로 수행할 수 없다고 본 이유 중 일부가 구체적이지 않다."
          ]
        },
        "poor": {
          "criteria": [
            "투약을 멈춘 판단의 근거를 제시하지 못하고 확인이 중요하다는 일반론만 말한다.",
            "당시 처방에서 무엇이 의심스러웠는지 또는 그 의심이 투약 중단으로 이어진 이유가 드러나지 않는다."
          ]
        }
      }
    },
    {
      "categoryId": "P03-C1",
      "itemId": "P03-C1-I2",
      "interviewBlueprint": {
        "questionIntent": "관찰한 환자 상태 변화를 다음 근무자가 파악할 수 있도록 인수인계하는 행동을 검증한다. 활력징후와 통증 관찰 내용을 인계하면서 중요하게 전달한 내용에 초점을 둔다.",
        "questionType": "behavioral",
        "expectedSTAR": {
          "situation": "정형외과 병동에서 활력징후와 통증을 관찰한 환자의 상태 변화를 다음 근무자에게 인계하는 상황이다.",
          "task": "다음 근무자가 환자의 상태 변화를 놓치지 않도록 중요한 관찰 내용을 전달해야 했다.",
          "action": "인계에서 중요하게 전달한 상태 변화와 그 내용을 전달한 이유를 구체적으로 설명한다.",
          "result": "관찰한 변화 중 무엇을 중요하게 인계했는지가 분명하게 드러난다."
        },
        "expectedEvidence": [
          "다음 근무자에게 가장 중요하게 전달한 환자 상태 변화의 내용",
          "해당 변화를 보여 주는 관찰 시점과 이전 상태 대비 차이",
          "그 내용을 인계에서 중요하게 전달한 이유"
